{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Thalidomide, a neutral poorly soluble tricyclic drug with slow oral absorption, has probably high absolute oral bioavailability (80–100% at low doses), supporting high F for the similarly neutral, poorly soluble tricyclic carbamazepine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Saccharin in the fed state had a fraction absorbed of 0.80±0.05 versus i.v., directly demonstrating high oral bioavailability under fed conditions and supporting high F for the query under fed state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Tocainide absolute oral bioavailability is about 100% in healthy volunteers, showing that a small oral drug can be essentially completely absorbed; this supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Phenylbutyrate oral bioavailability was 78% in patients, a direct human oral bioavailability value well above the 20% threshold; this supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Temozolomide oral bioavailability is close to 100% versus IV, demonstrating near-complete absorption for an oral agent; this supports high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues show oral bioavailability values well above the 20% threshold, including direct fed-state data and structurally related poorly soluble tricyclic drugs. The query carbamazepine is therefore predicted to have high absolute oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct carbamazepine oral bioavailability record is present in the supplied evidence.",
    "Food-effect on carbamazepine absorption is not directly measured, though fed-state saccharin data support high bioavailability under fed conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

